from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import IpacleanerURI


class IpacleanerV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_supported_boot_devices(self, node_id, timeout=60):
        uri = IpacleanerURI().ipacleaner_boot_devices_uri + f"/{node_id}/supported"
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def set_boot_parameters(self, node_id, boot_device, timeout=60, **kwargs):
        uri = IpacleanerURI().ipacleaner_boot_devices_uri
        data = {
            "node_id": node_id,
            "boot_device": boot_device,
        }
        if "persistent" in kwargs:
            data["persistent"] = kwargs["persistent"]
        if "efiboot" in kwargs:
            data["efiboot"] = kwargs["efiboot"]
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def get_boot_parameters(self, node_id, timeout=60):
        uri = IpacleanerURI().ipacleaner_boot_devices_uri + f"/{node_id}"
        return self.api_client.send_get_request(uri=uri, timeout=timeout)
